mapper.select:
SELECT id, user_id, device_id, measure_time, systolic, diastolic, heart_rate FROM t_blood_pressure  AND id = #{id}
 AND user_id = #{userId}
 AND device_id = #{deviceId}
 AND measure_time = #{measureTime}
 AND systolic = #{systolic}
 AND diastolic = #{diastolic}
 AND heart_rate = #{heartRate} ORDER BY id DESC
